 "content": "from collections import deque


def transform(grid):
    """Repeat each colored seed pattern across its surrounding non-8 panel."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 8 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            seeds = [(rr, cc) for rr, cc in cells if grid[rr][cc] not in (0, 8)]
            if not seeds:
                continue
            r0 = min(rr for rr, _ in seeds)
            r1 = max(rr for rr, _ in seeds)
            c0 = min(cc for _, cc in seeds)
            c1 = max(cc for _, cc in seeds)
            ph, pw = r1-r0+1, c1-c0+1
            pattern = [grid[rr][c0:c1+1] for rr in range(r0, r1+1)]
            for rr, cc in cells:
                out[rr][cc] = pattern[(rr-r0) % ph][(cc-c0) % pw]
    return out


if __name__ == '__main__':
